using System.Text.Json.Serialization;

namespace ModelContextProtocol.Protocol;

/// <summary>
/// Represents a server's response to a <see cref="F:ModelContextProtocol.Protocol.RequestMethods.PromptsGet" /> request from the client.
/// </summary>
/// <remarks>
/// <para>
/// For integration with AI client libraries, <see cref="T:ModelContextProtocol.Protocol.GetPromptResult" /> can be converted to
/// a collection of <see cref="T:Microsoft.Extensions.AI.ChatMessage" /> objects using the <see cref="M:ModelContextProtocol.AIContentExtensions.ToChatMessages(ModelContextProtocol.Protocol.GetPromptResult)" /> extension method.
/// </para>
/// <para>
/// See the <see href="https://github.com/modelcontextprotocol/specification/blob/main/schema/">schema</see> for details.
/// </para>
/// </remarks>
public sealed class GetPromptResult : Result
{
	/// <summary>
	/// Gets or sets an optional description for the prompt.
	/// </summary>
	/// <remarks>
	/// <para>
	/// This description provides contextual information about the prompt's purpose and use cases.
	/// It helps developers understand what the prompt is designed for and how it should be used.
