using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer;

public class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the given text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize")] string text,
        [Description("Optional desired length: 'short', 'medium', or 'detailed'")] string length = "medium")
    {
        var systemMessage = length switch
        {
            "short" => "You are a concise summarizer. Produce a 1-2 sentence summary.",
            "detailed" => "You are a thorough summarizer. Produce a comprehensive summary covering all key points.",
            _ => "You are a helpful summarizer. Produce a clear, moderate-length summary.",
        };

        return new GetPromptResult
        {
            Description = "Summarization prompt",
            Messages =
            [
                new PromptMessage { Role = Role.Assistant, Content = new Content { Type = "text", Text = systemMessage } },
                new PromptMessage { Role = Role.User, Content = new Content { Type = "text", Text = $"Please summarize the following text:\n\n{text}" } },
            ]
        };
    }
}

